@functools.lru_cache(maxsize=1)
def _libc():
    lib = ctypes.CDLL(None)
    lib.getenv.restype = ctypes.c_char_p
    lib.getenv.argtypes = [ctypes.c_char_p]
    return lib


def _live_env(name):
    """The process's *current* environment, not the snapshot `os` holds.

    `os.environ` is filled once, when `os` is imported. A host app calling
    `setenv()` after `Py_Initialize` — which is what
    `ManimLib.renderConfiguration` does, and what ManimStudio's software-encoder
    toggle does per render — changes the real environment and nothing that
    `os.environ` can see. Reading through libc is the difference between a
    setting that works and one that silently does nothing.
    """
    try:
        raw = _libc().getenv(name.encode())
    except Exception:
        raw = None
    if raw is None:
        # Fall back to the snapshot, which is right for variables that were
        # set before the interpreter started.
        return _os.environ.get(name, "")
    return raw.decode(errors="replace")


def _env_int(name, default):
    """An integer from the environment, or the default if it is not usable."""
    raw = _live_env(name)
    if not raw:
        return default
    try:
        value = int(raw)
    except ValueError:
        print(f"[manim] {name}={raw!r} is not a number; using {default}", flush=True)
        return default
    if value < 0:
        print(f"[manim] {name}={value} is negative; using {default}", flush=True)
        return default
    return value


class RenderSettings:
    """The render pipeline's tunables, in one editable place.

    Set them before rendering::

        from manim.utils.ios_encoder import settings
        settings.frame_queue_budget_mb = 1024   # more overlap, more memory
        settings.video_codec = "hevc_videotoolbox"

    Each field is seeded from an environment variable at import, so the same
    knobs work without touching code; assigning afterwards wins, because it
    happens later. Nothing here is read until a render starts, so a scene file
    can set them at module level.
    """

    __slots__ = ("frame_queue_budget_mb", "frame_queue_frames",
                 "frame_queue_min", "frame_queue_max", "video_codec",
                 "_explicit")

    def __init__(self):
        object.__setattr__(self, "_explicit", frozenset())
        #: Memory the encoder queue may hold, in MB. The depth in *frames*
        #: follows from this and the render resolution, because thirty-two
        #: frames is 256 MB at 1080p and 4.25 GB at 8K.
        object.__setattr__(self, "frame_queue_budget_mb",
                           _env_int("OFFLINAI_MANIM_QUEUE_MB", 256))
        #: An exact depth, ignoring the budget. ``0`` is unbounded, as on
        #: desktop; ``None`` derives it from the budget.
        object.__setattr__(self, "frame_queue_frames",
                           _env_int("OFFLINAI_MANIM_QUEUE_FRAMES", None))
        #: Below two the renderer and the encoder stop overlapping at all, so
        #: a small budget at 8K would make the render slower rather than
        #: lighter. Raise or lower it if you know better for your device.
        object.__setattr__(self, "frame_queue_min",
                           _env_int("OFFLINAI_MANIM_QUEUE_MIN", 2))
        #: Past this the encoder is the bottleneck and more queue buys latency
        #: rather than throughput.
        object.__setattr__(self, "frame_queue_max",
                           _env_int("OFFLINAI_MANIM_QUEUE_MAX", 32))
        #: Force an encoder — "h264_videotoolbox", "hevc_videotoolbox",
        #: "mpeg4", "libx264"… ``None`` asks the hardware what it can do.
        codec = _live_env("OFFLINAI_MANIM_CODEC") or None
        if _live_env("OFFLINAI_MANIM_SOFTWARE_ENCODER") == "1":
            codec = "mpeg4"
        object.__setattr__(self, "video_codec", codec)

    def __setattr__(self, name, value):
        # Remember what Python set, so refreshing from the environment cannot
        # overwrite a script's own choice. Documented precedence: whoever
        # assigned last wins, and an explicit assignment is always last.
        if name in self.__slots__:
            object.__setattr__(self, "_explicit",
                               getattr(self, "_explicit", frozenset()) | {name})
        object.__setattr__(self, name, value)

    def refresh(self) -> "RenderSettings":
        """Re-read the environment for anything not set from Python.

        Called at the start of each render. A host app that sets its
        configuration after `Py_Initialize` — which is the normal shape, since
        the interpreter usually starts before the user picks a quality — writes
        an environment `os.environ` never sees, so seeding once at import lost
        it. Fields a script assigned are left alone.
        """
        explicit = getattr(self, "_explicit", frozenset())
        defaults = {
            "frame_queue_budget_mb": ("OFFLINAI_MANIM_QUEUE_MB", 256),
            "frame_queue_frames": ("OFFLINAI_MANIM_QUEUE_FRAMES", None),
            "frame_queue_min": ("OFFLINAI_MANIM_QUEUE_MIN", 2),
            "frame_queue_max": ("OFFLINAI_MANIM_QUEUE_MAX", 32),
        }
        for field, (var, default) in defaults.items():
            if field not in explicit:
                object.__setattr__(self, field, _env_int(var, default))
        if "video_codec" not in explicit:
            codec = _live_env("OFFLINAI_MANIM_CODEC") or None
            if _live_env("OFFLINAI_MANIM_SOFTWARE_ENCODER") == "1":
                codec = "mpeg4"
            object.__setattr__(self, "video_codec", codec)
        return self

    def frame_queue_depth(self, width: int, height: int) -> tuple[int, str]:
        """How many frames to queue at this resolution, and why that number.

        The reason travels with the number because both clamps make the budget
        an approximation rather than a promise, in opposite directions — a
        small budget at 8K still holds the floor, a large one at 1080p still
        stops at the ceiling. Without the reason, a setting that is being
        overruled looks like a setting that does nothing.
        """
        if self.frame_queue_frames is not None:
            return max(0, int(self.frame_queue_frames)), "set explicitly"

        frame_bytes = max(int(width) * int(height) * 4, 1)
        budget = max(int(self.frame_queue_budget_mb), 0) * 1024 * 1024
        fits = budget // frame_bytes
        low, high = max(int(self.frame_queue_min), 1), max(int(self.frame_queue_max), 1)
        depth = max(low, min(high, fits))
        if fits < low:
            reason = (f"floor of {low} (a {budget // (1024 * 1024)} MB budget "
                      f"fits {fits} at this resolution)")
        elif fits > high:
            reason = f"ceiling of {high} (more queue would buy latency, not speed)"
        else:
            reason = f"{budget // (1024 * 1024)} MB budget"
        return depth, reason

    def codec_for(self, width: int, height: int) -> tuple[str, "str | None"]:
        """The encoder and mp4 tag to use, honouring any override."""
        if self.video_codec:
            tag = "hvc1" if self.video_codec.startswith("hevc") else None
            return self.video_codec, tag
        return videotoolbox_codec(width, height)

    def __repr__(self):
        fields = ", ".join(f"{n}={getattr(self, n)!r}"
                           for n in self.__slots__ if not n.startswith("_"))
        return f"RenderSettings({fields})"


#: The instance the render pipeline reads. Assign to its fields to change it.
settings = RenderSettings()
